import{_ as t,o,c as a,ao as d}from"./chunks/framework.D54b0YE9.js";const g=JSON.parse('{"title":"Coming from NONMEM, Monolix, or nlmixr2","description":"","frontmatter":{},"headers":[],"relativePath":"coming-from-nonmem.md","filePath":"coming-from-nonmem.md"}'),i={name:"coming-from-nonmem.md"};function r(n,e,l,s,c,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="Coming-from-NONMEM,-Monolix,-or-nlmixr2" tabindex="-1">Coming from NONMEM, Monolix, or nlmixr2 <a class="header-anchor" href="#Coming-from-NONMEM,-Monolix,-or-nlmixr2" aria-label="Permalink to &quot;Coming from NONMEM, Monolix, or nlmixr2 {#Coming-from-NONMEM,-Monolix,-or-nlmixr2}&quot;">​</a></h1><p>A translation table for people who already write population models somewhere else. Nothing here is new functionality; it maps vocabulary you have onto the pages that document it.</p><h2 id="The-model" tabindex="-1">The model <a class="header-anchor" href="#The-model" aria-label="Permalink to &quot;The model {#The-model}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">There</th><th style="text-align:right;">Here</th><th style="text-align:right;">Documented in</th></tr></thead><tbody><tr><td style="text-align:right;"><code>$THETA</code>, <code>THETA(1)</code></td><td style="text-align:right;">named entries in <code>@fixedEffects</code>, e.g. <code>CL = RealNumber(1.0, scale=:log)</code></td><td style="text-align:right;"><a href="./model-building/fixed-effects">@fixedEffects</a></td></tr><tr><td style="text-align:right;"><code>$OMEGA</code>, <code>ETA(1)</code></td><td style="text-align:right;">a <code>RandomEffect</code> in <code>@randomEffects</code>, whose spread is an ordinary fixed effect</td><td style="text-align:right;"><a href="./model-building/random-effects">@randomEffects</a></td></tr><tr><td style="text-align:right;"><code>$SIGMA</code>, <code>EPS(1)</code></td><td style="text-align:right;">the observation distribution in <code>@formulas</code>, e.g. <code>y ~ Normal(pred, sigma)</code></td><td style="text-align:right;"><a href="./model-building/formulas">@formulas</a></td></tr><tr><td style="text-align:right;"><code>$PK</code></td><td style="text-align:right;"><code>@formulas</code> (and <code>@preDifferentialEquation</code> for quantities the ODE needs)</td><td style="text-align:right;"><a href="./model-building/formulas">@formulas</a></td></tr><tr><td style="text-align:right;"><code>$DES</code></td><td style="text-align:right;"><code>@DifferentialEquation</code></td><td style="text-align:right;"><a href="./model-building/differential-equation">@DifferentialEquation</a></td></tr><tr><td style="text-align:right;"><code>$ERROR</code></td><td style="text-align:right;">the <code>~</code> line in <code>@formulas</code></td><td style="text-align:right;"><a href="./model-building/formulas">@formulas</a></td></tr><tr><td style="text-align:right;"><code>$DATA</code>, <code>$INPUT</code></td><td style="text-align:right;">a <code>DataFrame</code> passed to <code>DataModel</code></td><td style="text-align:right;"><a href="./data-model-construction">Data Model Construction</a></td></tr><tr><td style="text-align:right;"><code>$ESTIMATION</code></td><td style="text-align:right;">the method object passed to <code>fit_model</code></td><td style="text-align:right;"><a href="./estimation/">Estimation</a></td></tr><tr><td style="text-align:right;"><code>$COVARIANCE</code></td><td style="text-align:right;"><code>compute_uq(res; method=:wald)</code></td><td style="text-align:right;"><a href="./uncertainty-quantification/wald">Wald</a></td></tr></tbody></table><p>Two differences worth knowing before you start:</p><ul><li><p><strong><code>OMEGA</code> and <code>SIGMA</code> are not separate blocks.</strong> Between-subject spread is a fixed effect like any other, so it can carry a prior, a bound, or a covariate dependence: <code>omega = RealNumber(0.3, scale=:log)</code> and then <code>eta = RandomEffect(Normal(0.0, omega); column=:ID)</code>.</p></li><li><p><strong>The residual model is a distribution, not an error structure.</strong> <code>y ~ Normal(pred, sigma)</code> is additive error; <code>y ~ Normal(pred, sigma * pred)</code> is proportional; <code>y ~ Normal(pred, sigma_add + sigma_prop * pred)</code> is combined. The same slot takes <code>Poisson</code>, <code>NegativeBinomial</code>, censored, and Markov outcomes.</p></li><li><p><strong>Exponentiation is a scale, not hand-written code.</strong> <code>scale=:log</code> on a parameter keeps it positive and lets the optimizer work on the log scale, which is what <code>CL = THETA(1)*EXP(ETA(1))</code> is doing by hand.</p></li></ul><h2 id="The-data-set" tabindex="-1">The data set <a class="header-anchor" href="#The-data-set" aria-label="Permalink to &quot;The data set {#The-data-set}&quot;">​</a></h2><p>NoLimits reads NONMEM-style event tables directly. Set <code>evid_col</code> on <code>DataModel</code> and the <code>AMT</code>, <code>RATE</code>, and <code>CMT</code> columns are parsed as events:</p><ul><li><p><code>EVID = 0</code> - observation row.</p></li><li><p><code>EVID = 1</code> - input event: instantaneous bolus when <code>RATE = 0</code>, constant-rate infusion when <code>RATE &gt; 0</code>.</p></li><li><p><code>EVID = 2</code> - reset event: sets the named compartment to <code>AMT</code>.</p></li></ul><p>There is no <code>MDV</code> column. A row is either an observation of the outcome or an event; event rows carry <code>missing</code> in the outcome column. <a href="./data-model-construction">Data Model Construction</a> shows a complete event table, and the <a href="./tutorials/mixed-effects-ode-mcem">ODE Model with Dosing</a> tutorial works through the same thing end to end.</p><h2 id="The-estimator" tabindex="-1">The estimator <a class="header-anchor" href="#The-estimator" aria-label="Permalink to &quot;The estimator {#The-estimator}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">There</th><th style="text-align:right;">Closest here</th></tr></thead><tbody><tr><td style="text-align:right;">NONMEM <code>METHOD=1 INTER</code> (FOCEI)</td><td style="text-align:right;"><a href="./estimation/focei"><code>FOCEI</code></a></td></tr><tr><td style="text-align:right;">NONMEM <code>METHOD=SAEM</code>, Monolix&#39;s default</td><td style="text-align:right;"><a href="./estimation/saem"><code>SAEM</code></a></td></tr><tr><td style="text-align:right;">NONMEM <code>$EST METHOD=IMP</code></td><td style="text-align:right;"><a href="./estimation/mcem"><code>MCEM</code></a></td></tr><tr><td style="text-align:right;">nlmixr2 <code>focei</code></td><td style="text-align:right;"><a href="./estimation/focei"><code>FOCEI</code></a> or <a href="./estimation/laplace"><code>Laplace</code></a></td></tr><tr><td style="text-align:right;">nlmixr2 <code>saem</code></td><td style="text-align:right;"><a href="./estimation/saem"><code>SAEM</code></a></td></tr><tr><td style="text-align:right;">A fully Bayesian re-analysis</td><td style="text-align:right;"><a href="./estimation/mcmc"><code>MCMC</code></a></td></tr></tbody></table><p>The names match, but the implementations are independent: do not expect objective-function values to be comparable across tools, and compare fits in predictive space instead. The <a href="/NoLimits.jl/dev/estimation/index#Choosing-a-Method">decision table</a> explains what each method assumes, and <a href="./tutorials/mixed-effects-multiple-methods">Multi-Method Comparison</a> fits one model with four of them.</p><h2 id="Where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#Where-to-go-next" aria-label="Permalink to &quot;Where to go next {#Where-to-go-next}&quot;">​</a></h2><ul><li><p><a href="./quickstart">Quickstart</a> - a complete model, fitted, in five steps.</p></li><li><p><a href="./data-model-construction">Data Model Construction</a> - every column convention and validation rule.</p></li><li><p><a href="./troubleshooting">Troubleshooting</a> - when a fit fails or does not converge.</p></li></ul>',15)])])}const f=t(i,[["render",r]]);export{g as __pageData,f as default};
